style.css:
@-moz-document domain("pinterest.com") {
/* ? CHOCOLATE PINTEREST THEME */

    :root {
        --chocolate: #3b2418 !important;
        --dark-chocolate: #2b1910 !important;
        --cream: #faf7f2 !important;
    }


    /* =========================
       PINTEREST LOGO
       ========================= */

    svg[aria-label="Pinterest"] path {
        fill: var(--chocolate) !important;
    }

    svg[aria-label="Pinterest"] {
        color: var(--chocolate) !important;
    }


    /* =========================
       RED BUTTONS
       ========================= */

    button[style*="background-color"],
    button[style*="background"] {
        --color-red: var(--chocolate) !important;
    }

    [data-test-id="pin-action-button"] {
        background-color: var(--chocolate) !important;
    }


    /* =========================
       SAVE BUTTON
       ========================= */

    [data-test-id="pin-save-button"],
    [data-test-id="pin-save-button"] button {
        background-color: var(--chocolate) !important;
        color: white !important;
    }


    /* =========================
       RED TEXT
       ========================= */

    [style*="color: rgb(230, 0, 35)"],
    [style*="color: rgb(189, 0, 0)"],
    [style*="color: #e60023"],
    [style*="color: #bd081c"] {
        color: var(--chocolate) !important;
    }


    /* =========================
       RED BACKGROUNDS
       ========================= */

    [style*="background-color: rgb(230, 0, 35)"],
    [style*="background-color: #e60023"],
    [style*="background: rgb(230, 0, 35)"],
    [style*="background: #e60023"] {
        background-color: var(--chocolate) !important;
        background: var(--chocolate) !important;
    }


    /* =========================
       RED SVG ICONS
       ========================= */

    svg[fill="#E60023"],
    svg[fill="#e60023"],
    svg[fill="#BD081C"],
    path[fill="#E60023"],
    path[fill="#e60023"],
    path[fill="#BD081C"] {
        fill: var(--chocolate) !important;
    }


    /* =========================
       HOVER STATES
       ========================= */

    button:hover {
        --hover-color: var(--dark-chocolate) !important;
    }


    /* =========================
       RED BORDERS
       ========================= */

    [style*="border-color: rgb(230, 0, 35)"],
    [style*="border-color: #e60023"] {
        border-color: var(--chocolate) !important;
    }


    /* =========================
       RED LINKS
       ========================= */

    a[style*="#E60023"],
    a[style*="#e60023"] {
        color: var(--chocolate) !important;
    }


    /* =========================
       PROFILE / FOLLOW BUTTONS
       ========================= */

    [data-test-id="user-follow-button"],
    [data-test-id="user-follow-button"] button {
        background-color: var(--chocolate) !important;
        color: white !important;
    }


    /* =========================
       NOTIFICATION BADGES
       ========================= */

    [aria-label*="notification"],
    [aria-label*="Notifications"] {
        --notification-color: var(--chocolate) !important;
    }


    /* =========================
       GENERAL PINTEREST RED
       ========================= */

    [class*="red"],
    [class*="Red"] {
        --red: var(--chocolate) !important;
    }
}
